contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker == address(this), "maker must be this test contract");
        require(baseAsset != address(0), "baseAsset nonzero");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        bool beforeCancelled = c.cancelledOrders(orderHash);
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterCancelled = c.cancelledOrders(orderHash);

        bool reverted2;
        try c.cancel(order) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        bool afterCancelled2 = c.cancelledOrders(orderHash);

        assert(reverted == false && reverted2 == false && beforeCancelled == false && afterCancelled == true && afterCancelled2 == true);
    }

    receive() external payable {}
}

