contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        bool isCall,
        bool isLong
    ) public payable {
        require(maker != address(0), "maker zero");
        require(baseAsset != address(0), "baseAsset zero");
        require(duration < 10_000 days, "duration too long");
        require(expiration > block.timestamp, "expiration in past");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);

        // Cancel as the maker: msg.sender is this test contract, so maker must be address(this).
        order.maker = address(this);
        c.cancel(order);
        require(c.cancelledOrders(orderHash), "cancel not recorded");

        // Now try to fill the same order; it must revert because it is cancelled.
        bool reverted;
        try c.fillOrder(order, "", new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

