        bytes32 oppositeHash = c.hashOppositeOrder(order);

        uint256 makerBefore = c.balanceOf(address(this));
        uint256 callerBefore = c.balanceOf(address(this));
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
