        try c.fillOrder(order, signature, floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool originalMintedAfter = false;
        address originalOwnerAfter = address(0);
        try c.ownerOf(originalPositionId) returns (address owner2) {
            originalOwnerAfter = owner2;
            originalMintedAfter = true;
        } catch {}

        bool oppositeMintedAfter = false;
        address oppositeOwnerAfter = address(0);
        try c.ownerOf(oppositePositionId) returns (address owner3) {
            oppositeOwnerAfter = owner3;
            oppositeMintedAfter = true;
        } catch {}

        assert(
            !reverted ||
            (originalPositionId != oppositePositionId &&
                originalMintedBefore == originalMintedAfter &&
                originalOwnerBefore == originalOwnerAfter &&
                oppositeMintedBefore == oppositeMintedAfter &&
                oppositeOwnerBefore == oppositeOwnerAfter)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address baseAsset
    ) public payable {
        require(maker != address(0), "maker zero");
        require(maker != address(this), "maker is test");
        require(duration < 10_000 days, "duration too long");
        require(expiration > block.timestamp, "expiration in past");
        require(baseAsset != address(0), "baseAsset zero");
        require(baseAsset.code.length > 0, "baseAsset not contract");
        require(premium > 0, "premium zero");

        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 positionId;
        bool reverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            positionId = pid;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            require(positionId != 0, "zero position id");
            require(c.ownerOf(positionId) == address(this), "caller not owner of short id");
            require(c.ownerOf(uint256(c.hashOrder(order))) == maker, "maker not owner of long id");
            require(c.positionExpirations(positionId) == block.timestamp + duration, "wrong expiration for short position");
            require(!c.exercisedPositions(positionId), "position should not be exercised initially");
        }

        assert(
            reverted ||
                (c.ownerOf(positionId) == address(this) &&
                    c.positionExpirations(positionId) == block.timestamp + duration &&
                    c.positionExpirations(positionId) > block.timestamp &&
                    !c.exercisedPositions(positionId))
        );
    }

    receive() external payable {}
}

